    while low <= high:
        mid = (low + high) // 2
        if arr[mid] == target:
            return mid
        elif arr[mid] < target:
            low = mid + 1
        else:
            high = mid - 1
    return -1''',
            devTip: "Sıralı bir dizide arama yaparken O(n) doğrusal arama yerine daima O(log n) ikili arama (binary search) tercih edin.",
